CREATE TABLE IF NOT EXISTS account_invitations (id VARCHAR(40) PRIMARY KEY, user_id VARCHAR(40) NOT NULL UNIQUE, token_hash VARCHAR(64) NOT NULL, email_hash VARCHAR(64) NOT NULL, auth_version INTEGER NOT NULL, expires_at VARCHAR(30) NOT NULL, used_at VARCHAR(30), revoked_at VARCHAR(30), created_by VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, source_inquiry_id VARCHAR(40) UNIQUE, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(source_inquiry_id) REFERENCES website_inquiries(id));
